entries[62049] = { ["name"] = "Moosbeerenchutney", ["text"] = "Wirken in 2 sek.\nReagenzien:\nSäuerliche Sumpfmoosbeeren , Honig\nBenötigt Pilgerfreudenfest\nBenutzen: Stellt im Verlauf von 30 Sek. pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und 1 Stunde lang Eure Zaubermacht um [floor(cond([Quellwert]( 85, 15), 85 - 15, 0) * 0.6616) + 4] und Eure Ausdauer um [floor(cond([Quellwert]( 85, 15), 85 - 15, 0) * 0.554) + 4] erhöht.", ["unresolvedValues"] = true }
entries[62050] = { ["name"] = "Gewürzbrotfüllung", ["text"] = "Wirken in 2 sek.\nReagenzien:\nGewürzbrot , Herbstliche Gewürze\nBenötigt Pilgerfreudenfest\nBenutzen: Stellt im Verlauf von 30 Sek. pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und 1 Stunde lang Eure Trefferwertung und Ausdauer um [floor(cond([Quellwert]( 85, 15), 85 - 15, 0) * 0.554) + 4] erhöht.", ["unresolvedValues"] = true }
entries[62051] = { ["name"] = "Kandierte Süßkartoffel", ["text"] = "Wirken in 2 sek.\nReagenzien:\nSüßkartoffel von Teldrassil , Honig , Herbstliche Gewürze\nBenötigt Pilgerfreudenfest\nBenutzen: Stellt im Verlauf von 30 Sek. pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und Eure Tempowertung und Ausdauer wird 1 Stunde lang um [floor(cond([Quellwert]( 85, 15), 85 - 15, 0) * 0.8) + 4] erhöht.", ["unresolvedValues"] = true }
