entries[62269] = { ["name"] = "Rune des Todes", ["text"] = "Unbegrenzte Reichweite\nSofort\nBeschwört eine Rune des Todes am Ort eines zufälligen feindlichen Ziels. Diese Rune verursacht bei allen innerhalb von 13 Metern um diesen Ort 2750 Schattenschaden alle 0,5 Sekunden." }
entries[62271] = { ["name"] = "Unzerstörbare Heilungsverstärker", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer\nReagenzien:\nTitanbarren (8), Schweres boreanisches Leder (4), Waldsmaragd (2), Äonenerde (4), Gefrorene Kugel\nUnzerstörbare Heilungsverstärker\nWird beim Aufheben gebunden\nKopf Platte\n1899 Rüstung\n+109 Ausdauer\n+74 Intelligenz\n\nMetasockel\nGelber Sockel\nSockelbonus: +9 Zaubermacht\n\nHaltbarkeit 100 / 100\n72\nBenötigt Ingenieurskunst\n(400)\nAnlegen: Erhöht die kritische Trefferwertung um 73.\nBenutzen: Ermöglicht Euch, in weite Entfernungen zu sehen. (3 Sek. Abklingzeit)" }
entries[62272] = { ["name"] = "Raelorasz' Funken", ["text"] = "20 Meter Reichweite\nSofort\nZündet ein Signalfeuer an, das Keristrasza an Euren Standort beschwört." }
