entries[62274] = { ["name"] = "Runenschild", ["text"] = "Wirken in 1.5 sek.\nBedeckt den Zaubernden mit magischen Runen, die bis zu 20000 Schaden absorbieren. Sobald 20000 Schaden absorbiert wurde, wird dieser in eine mächtige Energieexplosion umgewandet, die den Schaden des Zaubernden 15 Sek. lang um 50% erhöht." }
