entries[62321] = { ["name"] = "Runenschild", ["text"] = "330 Mana 30 Meter Reichweite\nWirken in 0.5 sek. 6 sek. Abklingzeit\nUmgibt den Zaubernden mit einer Runenbarriere, die 40000 magischen Schaden absorbiert und den erlittenen körperlichen Schaden um 50% verringert." }
