entries[62331] = { ["name"] = "Durchbohren", ["text"] = "Nahkampfreichweite\nSofort\nEin hinterhältiger Angriff, der das Ziel bis zu einer Heilung von über 90% der maximalen Gesundheit stark bluten lässt. Verursacht 1 Min. lang oder bis zur Heilung alle 2 Sek. 1125 Schaden." }
