entries[62335] = { ["name"] = "Heilige Pein", ["text"] = "50 Meter Reichweite\nWirken in 1.5 sek.\nZerschmettert einen Feind und fügt ihm 4950 to 6050 Heiligschaden zu." }
entries[62336] = { ["name"] = "Hakenwurfaura", ["text"] = "Unbegrenzte Reichweite\nSofort\nBenutzt Eure Harpune, um auf der nahen Leviathan zu landen." }
