entries[62344] = { ["name"] = "Fäuste aus Stein", ["text"] = "Wirken in 2.5 sek. 10 sek. Abklingzeit\nDie Steinfäuste verlangsamen das Bewegungstempo des Zaubernden um 20% und erhöhen den verursachten Schaden um 250%. Zusätzlich haben die vernichtenden Angriffe die Chance, dem Ziel die Knochen zu brechen, was dessen Chance zu blockieren, auszuweichen oder zu parieren 20 Sek. lang um 100% senkt.\n(5s Abklingzeit)" }
entries[62345] = { ["name"] = "Rammen", ["text"] = "40 Energie 15 Meter Reichweite\nSofort\nRammt alle Feinde, die sich vor dem Verwüster befinden, verursacht 22501 to 27501 Schaden und stößt sie zurück. Verursacht zudem bei Gebäuden 2850 to 3150 Belagerungsschaden." }
