entries[62347] = { ["name"] = "Netherschock", ["text"] = "20 Meter Reichweite\nSofort 40 sek. Abklingzeit\nPeitscht sofort nach einem Feind, unterbricht das Wirken von Zaubern und verhindert 2 Sek. lang, dass ein Zauber dieser Art gewirkt werden kann." }
