entries[62351] = { ["name"] = "Erfrischung", ["text"] = "Sofort\nStellt im Verlauf von 30 Sek. insgesamt 22500 Gesundheit wieder her. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 30 Trefferwertung und 40 Ausdauer." }
