entries[62354] = { ["name"] = "Gebrochene Knochen", ["text"] = "Unbegrenzte Reichweite\nSofort\nEin massiver Angriff, der die Knochen des Ziels bricht, wodurch es nicht mehr Blocken, Ausweichen oder Parieren kann." }
entries[62355] = { ["name"] = "Volldampf voraus!", ["text"] = "70 Meter Reichweite\nSofort\nSchaltet die Dampfmaschine eine kurze Zeit lang in den Overdrive und lässt sie nach vorne schnellen." }
