entries[62373] = { ["name"] = "Geschmolzen", ["text"] = "100 Meter Reichweite\nSofort\nDer Zaubernde wird geschmolzen, sein Tempo um 100% erhöht. Pro Sekunde schlagen Flammen aus dem Zaubernden und verursachen an allen Feinden innerhalb von 7 Metern 1885 to 2115 Feuerschaden." }
