entries[62425] = { ["name"] = "Druck auf Waffensystemen leiten", ["text"] = "200 Mana\nSofort 10 sek. Abklingzeit\nLeitet den gesamten Motorendruck zu den Waffensystemen.\n\n200-500 Druck:\nUm 20% erhöhter Schaden.\nHält 20 Sek. lang an.\n\n500-800 Druck:\nUm 30% erhöhter Schaden.\nHält 30 Sek. lang an.\n\n800-1100 Druck:\nUm 40% erhöhter Schaden.\nHält 40 Sek. lang an.\n\n1100+ Druck:\nUm 50% erhöhter Schaden.\nHält 50 Sek. lang an." }
